#' Regressions
#'
#' 
#' @param data A data.frame.
#' @param outcome The outcome variable(s). One model is built per outcome. Set
#'   each outcome's family (and, for a binomial outcome, its modelled level or
#'   number of trials) in the Model table.
#' @param predictors The explanatory variables of the model. Factors are shown
#'   one line per level (the reference level as the neutral value); numeric
#'   predictors as a single line.
#' @param tab_vars A grouping variable. The same model is fitted within each
#'   of its levels and the tables are stacked (like tab_vars for crosstables).
#' @param wt A survey weight variable. Switches to design-based estimation
#'   (scale-invariant sandwich standard errors). Leave empty for unweighted
#'   results.
#' @param family .
#' @param link WHICH MEASURE THE MODEL ESTIMATES -- the only argument that
#'   changes the model. A link IS  a measure, so it takes the same words as
#'   \code{measure}. Chosen per outcome, in the  Model table beside
#'   \code{family}: \code{"auto"} is the family's own (a logistic  regression
#'   for a binary outcome, a linear one for a quantity, a Poisson one for a
#'   count), and \code{"odds_ratio"} / \code{"ratio"} / \code{"difference"} name
#'   the model  whose coefficient IS that measure -- on a binary outcome, the
#'   logistic fit, the modified  Poisson (Zou 2004) and the identity-link
#'   additive-risk one. The picker only ever offers  the links the chosen family
#'   can be fitted on.
#' @param outcome_level .
#' @param trials .
#' @param effect WHERE THE NUMBER COMES FROM, once the model and the reported
#'   measure are fixed.  \itemize{   \item \code{"auto"}: the coefficients when
#'   the reported measure IS the model's own,   the model's predictions
#'   otherwise. Nobody needs to change this.   \item \code{"conditional"}: read
#'   off the model's own coefficients.   \item \code{"marginal"}: worked out
#'   from the model's predictions for every observed   person, then averaged.
#'   \item \code{"at_reference"}: the same, at one profile (every other
#'   predictor at its   reference level / mean).  }
#' @param measure WHICH MEASURE IS REPORTED. It never changes the model: where
#'   it is not the measure the  model estimates (see \code{link}), it is worked
#'   out from the model's predictions.  \itemize{   \item \code{"auto"}: the
#'   model's own measure -- follow from the left. On a prediction   route it
#'   steps back to the outcome's own (a percentage reads as "x times as
#'   likely"),   because a marginal odds ratio is a specialist quantity, asked
#'   for by name.   \item \code{"odds_ratio"} / \code{"ratio"} /
#'   \code{"difference"}: the named measure,   when the outcome's level can
#'   carry it. One it cannot says so, and lists what it does   offer.   \item
#'   \code{"log"}: the same estimand, left un-exponentiated.  }
#' @param empirical Show the crude, unadjusted, single-predictor effect beside
#'   each model effect --- the bivariate association that IS the modelised
#'   quantity when there is a single predictor, so the gap between the two is
#'   what adjustment changed. \code{"column"} draws it as its own column;
#'   \code{"cell"} folds it into the model cell instead, which is the default
#'   for a 3+ level outcome, where one model column would otherwise need one
#'   crude column per category.
#' @param models .
#' @param stats_baseline .
#' @param stats_compare With several models (a predictor-subset list), add a
#'   likelihood-ratio / F / Wald comparison-test footer row: "compare_baseline"
#'   tests each model against the chosen baseline model, "sequential" against
#'   the previous one (an AIC difference when not nested).
#' @param stats_checks Also run the model checks that have to refit the model
#'   (linearity of a numeric predictor, proportional odds). They are off by
#'   default because they dominate the cost of a table; everything else in the
#'   model-summary footer is always shown.
#' @param na "drop_by_outcome" (default) fits every model OF ONE OUTCOME on
#'   the same complete cases, which is what makes the observed columns
#'   comparable to the model beside them and lets the likelihood-ratio
#'   comparison run; "drop_by_model" gives each model its own complete cases (a
#'   model on a different population then gets no observed effect); "drop_all"
#'   shares one population across every outcome as well.
#' @param run_compare .
#' @param levels_collapse .
#' @param crosses .
#' @param ref_levels .
#' @param shape .
#' @param multiplier .
#' @param conf_level The confidence level for intervals and the significance
#'   stars.
#' @param ci_method Wald intervals (also the only option for weighted models)
#'   or profile-likelihood intervals (unweighted binomial / poisson only; needs
#'   MASS).
#' @param stars Show per-cell significance stars (the colours read the
#'   confidence interval either way).
#' @param color WHAT the effect cells are coloured by. The colour LADDER
#'   always comes from what the  column estimates (an odds ratio is read on the
#'   odds-ratio scale, a beta on the  standardized-difference one), so what is
#'   left to choose is what the estimate is compared  TO.  \itemize{   \item
#'   \code{"auto"}: the effect's own size (compared to no effect).   \item
#'   \code{"no"}: no colours.   \item \code{"adjustment"}: how far the ADJUSTED
#'   effect moved from the crude one --   needs \code{empirical}.   \item
#'   \code{"between_groups"}: how far each group's effect is from the first
#'   group's   -- needs \code{tab_vars}.  }
#' @param color_signif How significance interacts with the colours: observed
#'   size + grey out non-significant cells, colour only the guaranteed
#'   (error-adjusted) effect, ignore significance.
#' @param display The estimate-cell LAYOUT (never the estimand: a display may
#'   fold in another quantity of the SAME fit, it can never change the fit). The
#'   same named layouts \code{tab()} offers, written in the same \code{\{\}}
#'   grammar: \code{est} is whatever the column estimates and \code{base} the
#'   level it sits on (an adjusted probability, an adjusted mean). \code{"auto"}
#'   keeps the built-in layout.
#' @param n The column giving the number of observations behind each predictor
#'   level: \code{"range"} prints \code{min-max} when several models were fitted
#'   on different people, \code{"min"} the smallest count only, \code{"no"} no
#'   column at all.
#' @param cleannames Strip numeric prefixes from factor level labels.
#' @param subtext A free note printed below the table.
#' @param wrap_rows .
#' @param wrap_cols .
#' @param export_format .
#' @param exportExcel Press to export the table to the chosen format (the
#'   button label follows the format).
#' @param export_dir The folder to save the exported file in. Blank or
#'   \code{~/Documents} auto-detects your real Documents folder (a redirected
#'   \code{D:/Documents} or network Documents included). Type any other folder
#'   to override; a leading \code{~} there expands to your home folder.
#' @param export_filename The bare file name, with NO extension (the chosen
#'   format adds it).
#' @param resetPath Reset the folder and file name to their defaults (your
#'   Documents folder and "Regression").
#' @param xl_check Excel export only: draw the model-check plots
#'   (\code{reg_check_plots()}) under each table in the workbook. \code{"auto"}
#'   takes the panels that apply to the fitted family, \code{"all"} adds
#'   dispersion and collinearity. Needs \code{ggplot2} and \code{gridExtra};
#'   without them the export says so and writes the table alone.
#' @param xl_replace "Set to \code{TRUE} to overwrite an existing file."
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$html_table} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$cache_state} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$compare_state} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' @export
jmvtabreg <- function(
    data,
    outcome = NULL,
    predictors = NULL,
    tab_vars = NULL,
    wt = NULL,
    family = NULL,
    link = NULL,
    outcome_level = NULL,
    trials = NULL,
    effect = "auto",
    measure = "auto",
    empirical = "no",
    models = NULL,
    stats_baseline = 1,
    stats_compare = "none",
    stats_checks = FALSE,
    na = "drop_by_outcome",
    run_compare = FALSE,
    levels_collapse = NULL,
    crosses = NULL,
    ref_levels = NULL,
    shape = NULL,
    multiplier = NULL,
    conf_level = 0.95,
    ci_method = "wald",
    stars = TRUE,
    color = "auto",
    color_signif = "grey_non_signif",
    display = "auto",
    n = "range",
    cleannames = TRUE,
    subtext = "",
    wrap_rows = 35,
    wrap_cols = 15,
    export_format = "excel",
    exportExcel = FALSE,
    export_dir = "~/Documents",
    export_filename = "Reg_model",
    resetPath = FALSE,
    xl_check = "no",
    xl_replace = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("jmvtabreg requires jmvcore to be installed (restart may be required)")

    if ( ! missing(outcome)) outcome <- jmvcore::resolveQuo(jmvcore::enquo(outcome))
    if ( ! missing(predictors)) predictors <- jmvcore::resolveQuo(jmvcore::enquo(predictors))
    if ( ! missing(tab_vars)) tab_vars <- jmvcore::resolveQuo(jmvcore::enquo(tab_vars))
    if ( ! missing(wt)) wt <- jmvcore::resolveQuo(jmvcore::enquo(wt))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(outcome), outcome, NULL),
            `if`( ! missing(predictors), predictors, NULL),
            `if`( ! missing(tab_vars), tab_vars, NULL),
            `if`( ! missing(wt), wt, NULL))

    for (v in tab_vars) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- jmvtabregOptions$new(
        outcome = outcome,
        predictors = predictors,
        tab_vars = tab_vars,
        wt = wt,
        family = family,
        link = link,
        outcome_level = outcome_level,
        trials = trials,
        effect = effect,
        measure = measure,
        empirical = empirical,
        models = models,
        stats_baseline = stats_baseline,
        stats_compare = stats_compare,
        stats_checks = stats_checks,
        na = na,
        run_compare = run_compare,
        levels_collapse = levels_collapse,
        crosses = crosses,
        ref_levels = ref_levels,
        shape = shape,
        multiplier = multiplier,
        conf_level = conf_level,
        ci_method = ci_method,
        stars = stars,
        color = color,
        color_signif = color_signif,
        display = display,
        n = n,
        cleannames = cleannames,
        subtext = subtext,
        wrap_rows = wrap_rows,
        wrap_cols = wrap_cols,
        export_format = export_format,
        exportExcel = exportExcel,
        export_dir = export_dir,
        export_filename = export_filename,
        resetPath = resetPath,
        xl_check = xl_check,
        xl_replace = xl_replace)

    analysis <- jmvtabregClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

